--- a/rtl/hough.sv
+++ b/rtl/hough.sv
@@ -9,9 +9,8 @@
 // Read port: rd_theta (k), rd_rho (cell) select a cell and rd_cnt shows its 16-bit count one clock later. rst_n is synchronous, active low (it does not clear the cells).
 // The tables are computed by a CORDIC or a small ROM; lesson 8 discusses which and the cost.
 //
-// Block-RAM form (07a1c): the 1536 counts live in two block RAMs written together (one read port each: the read-modify-write of a vote, and the read port), and one
+// Block-RAM form: the 1536 counts live in two block RAMs written together (one read port each: the read-modify-write of a vote, and the read port), and one
 // valid bit per cell in flip-flops. A cell whose valid bit is 0 reads as 0, so `clear` still zeroes every cell in ONE clock (it clears the valid bits, not the RAMs).
-// A vote takes four clocks after its angle clock (distance register, index register, read, write), so busy stays high four clocks longer than before; a read sees the same value one clock after the select.
 module hough_cell_ram #(
     parameter int N = 1536
 ) (
@@ -66,6 +65,7 @@
             default: ctab = 0;
         endcase
     endfunction
+
     function automatic signed [8:0] stab(input [3:0] k);
         case (k)
             4'd0: stab = 0;
@@ -87,57 +87,131 @@
             default: stab = 0;
         endcase
     endfunction
+
     localparam int NC = NT * NR;
+
     logic [NC-1:0] vld;       // a cell that was never voted since the last clear reads as 0
     initial vld = '0;
-    logic [7:0]  x, y;
-    logic [4:0]  k;          // 0 .. NT-1 while busy
-    integer rho;
+
+    logic [7:0] x, y;
+    logic [4:0] k;
     logic start_q;
-    logic signed [15:0] rho_r;  logic [3:0] k_r;  logic p_en;   // stage P: the distance, registered
-    logic        s0_en, s0_vote, s1_en, s1_vote, vld_a, vld_b;   // stage 0: index registered; stage 1: the vote's RAM read is on q_a
-    logic [10:0] s0_idx, s1_idx;
+    wire launch = start_q || (k != 0);
+
+    // DSP48E1 multiply pipeline. These datapath registers intentionally have no reset.
+    logic signed [8:0]  ax_r, bx_r, ay_r, by_r;
+    logic signed [17:0] mx_r, my_r;
+    logic signed [17:0] px_r, py_r;
+
+    always_ff @(posedge clk) begin
+        ax_r <= $signed({1'b0, x});
+        bx_r <= ctab(k[3:0]);
+        ay_r <= $signed({1'b0, y});
+        by_r <= stab(k[3:0]);
+
+        mx_r <= ax_r * bx_r;
+        my_r <= ay_r * by_r;
+
+        px_r <= mx_r;
+        py_r <= my_r;
+    end
+
+    // Fabric pipeline: sum the products, apply the fixed-point rounding and select the bin.
+    logic valid0, valid1, valid2, valid3;
+    logic [3:0] theta0, theta1, theta2, theta3;
+    logic signed [18:0] sum_r;
+    logic [10:0] addr5;
+    logic vote5;
+
+    always_ff @(posedge clk) begin
+        valid0 <= launch;
+        theta0 <= k[3:0];
+        valid1 <= valid0;
+        theta1 <= theta0;
+        valid2 <= valid1;
+        theta2 <= theta1;
+
+        sum_r <= {{1{px_r[17]}}, px_r} + {{1{py_r[17]}}, py_r};
+        valid3 <= valid2;
+        theta3 <= theta2;
+
+        if (valid3) begin
+            // Keep the rounding addition and arithmetic shift bit-for-bit equivalent to the reference.
+            if (((($signed(sum_r) + 19'sd64) >>> 7) + ROFF) >= 0 &&
+                ((($signed(sum_r) + 19'sd64) >>> 7) + ROFF) < NR) begin
+                addr5 <= 11'(theta3 * NR + ((($signed(sum_r) + 19'sd64) >>> 7) + ROFF));
+                vote5 <= 1'b1;
+            end else begin
+                addr5 <= 11'd0;
+                vote5 <= 1'b0;
+            end
+        end else begin
+            addr5 <= 11'd0;
+            vote5 <= 1'b0;
+        end
+
+        if (!rst_n) begin
+            valid0 <= 1'b0;
+            valid1 <= 1'b0;
+            valid2 <= 1'b0;
+            valid3 <= 1'b0;
+            vote5 <= 1'b0;
+        end
+    end
+
+    logic read_valid;
+    logic [10:0] wr_addr;
+    logic vld_a, vld_b;
     logic [15:0] q_a, q_b;
-    assign busy = (k != 0) || start_q || p_en || s0_en || s1_en;
-
-    // stage 0 (the angle clock): the cell index of this angle's vote
-    always_comb rho = (($signed({1'b0, x}) * ctab(k[3:0]) + $signed({1'b0, y}) * stab(k[3:0]) + 64) >>> 7) + ROFF;
-    wire         vote0 = p_en && rho_r >= 0 && rho_r < NR;
-    wire  [10:0] idx0  = 11'(k_r * NR + rho_r);
-    wire  [10:0] ridx  = 11'(rd_theta * NR + rd_rho);
-    wire  [15:0] newc  = (vld_a ? q_a : 16'd0) + 16'd1;
-
-    hough_cell_ram #(.N(NC)) u_a (.clk(clk), .we(s1_vote), .waddr(s1_idx), .wdata(newc), .raddr(s0_idx), .rdata(q_a));
-    hough_cell_ram #(.N(NC)) u_b (.clk(clk), .we(s1_vote), .waddr(s1_idx), .wdata(newc), .raddr(ridx), .rdata(q_b));
+
+    wire [10:0] ridx = 11'(rd_theta * NR + rd_rho);
+    wire [15:0] newc = (vld_a ? q_a : 16'd0) + 16'd1;
+
+    hough_cell_ram #(.N(NC)) u_a (
+        .clk(clk), .we(read_valid), .waddr(wr_addr), .wdata(newc),
+        .raddr(addr5), .rdata(q_a)
+    );
+    hough_cell_ram #(.N(NC)) u_b (
+        .clk(clk), .we(read_valid), .waddr(wr_addr), .wdata(newc),
+        .raddr(ridx), .rdata(q_b)
+    );
+
     assign rd_cnt = vld_b ? q_b : 16'd0;

     always_ff @(posedge clk) begin
+        read_valid <= vote5;
+        wr_addr <= addr5;
+        vld_a <= vld[addr5];
         vld_b <= vld[ridx];
-        vld_a <= vld[s0_idx];
-        p_en <= start_q || k != 0;
-        rho_r <= 16'(rho);
-        k_r <= k[3:0];
-        s0_en <= p_en;
-        s0_vote <= vote0;
-        s0_idx <= idx0;
-        s1_en <= s0_en;
-        s1_vote <= s0_vote;
-        s1_idx <= s0_idx;
+
         if (!rst_n) begin
-            k <= 5'd0; start_q <= 1'b0; p_en <= 1'b0; s0_en <= 1'b0; s0_vote <= 1'b0; s1_en <= 1'b0; s1_vote <= 1'b0;
+            k <= 5'd0;
+            start_q <= 1'b0;
+            valid0 <= 1'b0;
+            valid1 <= 1'b0;
+            valid2 <= 1'b0;
+            valid3 <= 1'b0;
+            vote5 <= 1'b0;
+            read_valid <= 1'b0;
         end else begin
             start_q <= 1'b0;
-            if (clear && !busy) begin
+
+            if (clear && !busy)
                 vld <= '0;
-            end
-            if (s1_vote) vld[s1_idx] <= 1'b1;
+
+            if (read_valid)
+                vld[wr_addr] <= 1'b1;
+
             if (pt_valid && !busy) begin
-                x <= pt_x; y <= pt_y;
+                x <= pt_x;
+                y <= pt_y;
                 start_q <= 1'b1;
             end
-            if (start_q || k != 0) begin
+
+            if (launch)
                 k <= (k == NT - 1) ? 5'd0 : k + 5'd1;
-            end
         end
     end
+
+    assign busy = (k != 0) || start_q || valid0 || valid1 || valid2 || valid3 || vote5 || read_valid;
 endmodule
